package ccxt

type Btse struct {
	*BtseCore
	Core          *BtseCore
	exchangeTyped *ExchangeTyped
}

func NewBtse(userConfig map[string]any) *Btse {
	p := NewBtseCore()
	p.Init(userConfig)
	return &Btse{
		BtseCore:      p,
		Core:          p,
		exchangeTyped: NewExchangeTyped(&p.Exchange),
	}
}
func NewBtseFromCore(core *BtseCore) *Btse {
	return &Btse{
		BtseCore:      core,
		Core:          core,
		exchangeTyped: NewExchangeTyped(&core.Exchange),
	}
}

